package vn.hust.restaurant.repository;

import java.math.BigDecimal;import java.sql.*;import java.util.*;
import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.*;

public class OrderRepository {
    public Optional<OrderSummary> activeByTable(int tableId)throws SQLException{
        String sql="""
          SELECT TOP 1 p.MaPhieu,p.MaPhieuCode,p.MaBan,b.MaBanCode,n.HoTen,p.ThoiGianTao,p.TrangThaiPhieu,
            ISNULL(SUM(ct.SoLuong*ct.DonGiaTaiThoiDiem),0) Tong
          FROM PhieuGoiMon p JOIN BanAn b ON b.MaBan=p.MaBan JOIN NhanVien n ON n.MaNhanVien=p.MaNhanVienPhucVu
          LEFT JOIN ChiTietGoiMon ct ON ct.MaPhieu=p.MaPhieu AND ct.TrangThaiCheBien<>'DA_HUY'
          WHERE p.MaBan=? AND p.TrangThaiPhieu IN('MOI','DA_GUI_BEP','DANG_PHUC_VU','CHO_THANH_TOAN')
          GROUP BY p.MaPhieu,p.MaPhieuCode,p.MaBan,b.MaBanCode,n.HoTen,p.ThoiGianTao,p.TrangThaiPhieu ORDER BY p.ThoiGianTao DESC
          """;
        try(Connection c=Database.getConnection();PreparedStatement ps=c.prepareStatement(sql)){ps.setInt(1,tableId);try(ResultSet rs=ps.executeQuery()){return rs.next()?Optional.of(mapSummary(rs)):Optional.empty();}}
    }
    public List<OrderSummary> openOrders()throws SQLException{
        List<OrderSummary> out=new ArrayList<>();String sql="""
          SELECT p.MaPhieu,p.MaPhieuCode,p.MaBan,b.MaBanCode,n.HoTen,p.ThoiGianTao,p.TrangThaiPhieu,
            ISNULL(SUM(CASE WHEN ct.TrangThaiCheBien<>'DA_HUY' THEN ct.SoLuong*ct.DonGiaTaiThoiDiem ELSE 0 END),0) Tong
          FROM PhieuGoiMon p JOIN BanAn b ON b.MaBan=p.MaBan JOIN NhanVien n ON n.MaNhanVien=p.MaNhanVienPhucVu
          LEFT JOIN ChiTietGoiMon ct ON ct.MaPhieu=p.MaPhieu
          WHERE p.TrangThaiPhieu IN('MOI','DA_GUI_BEP','DANG_PHUC_VU','CHO_THANH_TOAN')
          GROUP BY p.MaPhieu,p.MaPhieuCode,p.MaBan,b.MaBanCode,n.HoTen,p.ThoiGianTao,p.TrangThaiPhieu ORDER BY p.ThoiGianTao
          """;try(Connection c=Database.getConnection();Statement st=c.createStatement();ResultSet rs=st.executeQuery(sql)){while(rs.next())out.add(mapSummary(rs));}return out;
    }
    public long create(int tableId,int employeeId)throws SQLException{return Database.inTransaction(c->{try(PreparedStatement lock=c.prepareStatement("SELECT TrangThai FROM BanAn WITH(UPDLOCK,HOLDLOCK) WHERE MaBan=?")){lock.setInt(1,tableId);try(ResultSet rs=lock.executeQuery()){if(!rs.next())throw new SQLException("Bàn không tồn tại");String s=rs.getString(1);if(!List.of("TRONG","DA_DAT").contains(s))throw new SQLException("Bàn đang được phục vụ hoặc ngừng sử dụng");}}try(PreparedStatement ck=c.prepareStatement("SELECT 1 FROM PhieuGoiMon WHERE MaBan=? AND TrangThaiPhieu IN('MOI','DA_GUI_BEP','DANG_PHUC_VU','CHO_THANH_TOAN')")){ck.setInt(1,tableId);try(ResultSet rs=ck.executeQuery()){if(rs.next())throw new SQLException("Bàn đã có order đang hoạt động");}}long id;String code="ORD"+System.currentTimeMillis();try(PreparedStatement ps=c.prepareStatement("INSERT PhieuGoiMon(MaPhieuCode,MaBan,MaNhanVienPhucVu,ThoiGianTao,TrangThaiPhieu) OUTPUT INSERTED.MaPhieu VALUES(?,?,?,SYSDATETIME(),'MOI')")){ps.setString(1,code);ps.setInt(2,tableId);ps.setInt(3,employeeId);try(ResultSet rs=ps.executeQuery()){rs.next();id=rs.getLong(1);}}try(PreparedStatement ps=c.prepareStatement("UPDATE BanAn SET TrangThai='DANG_PHUC_VU' WHERE MaBan=?")){ps.setInt(1,tableId);ps.executeUpdate();}return id;});}
    public void addItem(long orderId,int menuItemId,int qty,String note)throws SQLException{if(qty<=0)throw new SQLException("Số lượng phải lớn hơn 0");Database.inTransaction(c->{BigDecimal price;try(PreparedStatement ps=c.prepareStatement("SELECT DonGia,TrangThaiPhucVu FROM MonAn WHERE MaMon=?")){ps.setInt(1,menuItemId);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new SQLException("Món không tồn tại");if(!"CON_MON".equals(rs.getString(2)))throw new SQLException("Món đang hết/phục vụ tạm ngừng");price=rs.getBigDecimal(1);}}try(PreparedStatement ps=c.prepareStatement("SELECT TrangThaiPhieu FROM PhieuGoiMon WITH(UPDLOCK) WHERE MaPhieu=?")){ps.setLong(1,orderId);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new SQLException("Order không tồn tại");if(!List.of("MOI","DA_GUI_BEP","DANG_PHUC_VU").contains(rs.getString(1)))throw new SQLException("Order không cho phép thêm món");}}try(PreparedStatement ps=c.prepareStatement("INSERT ChiTietGoiMon(MaPhieu,MaMon,SoLuong,DonGiaTaiThoiDiem,GhiChuRieng,TrangThaiCheBien,DaTruKho) VALUES(?,?,?,?,?,'CHO_LAM',0)")){ps.setLong(1,orderId);ps.setInt(2,menuItemId);ps.setInt(3,qty);ps.setBigDecimal(4,price);ps.setString(5,note);ps.executeUpdate();}return null;});}
    public List<OrderItemView> items(long orderId)throws SQLException{List<OrderItemView> out=new ArrayList<>();String sql="SELECT ct.MaCTGoiMon,ct.MaPhieu,ct.MaMon,m.TenMon,ct.SoLuong,ct.DonGiaTaiThoiDiem,ct.GhiChuRieng,ct.TrangThaiCheBien,ct.DaTruKho FROM ChiTietGoiMon ct JOIN MonAn m ON m.MaMon=ct.MaMon WHERE ct.MaPhieu=? ORDER BY ct.MaCTGoiMon";try(Connection c=Database.getConnection();PreparedStatement ps=c.prepareStatement(sql)){ps.setLong(1,orderId);try(ResultSet rs=ps.executeQuery()){while(rs.next())out.add(new OrderItemView(rs.getLong(1),rs.getLong(2),rs.getInt(3),rs.getString(4),rs.getInt(5),rs.getBigDecimal(6),rs.getString(7),rs.getString(8),rs.getBoolean(9)));}}return out;}
    public void removeItem(long id)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement ps=c.prepareStatement("UPDATE ChiTietGoiMon SET TrangThaiCheBien='DA_HUY' WHERE MaCTGoiMon=? AND TrangThaiCheBien='CHO_LAM'")){ps.setLong(1,id);if(ps.executeUpdate()==0)throw new SQLException("Chỉ được hủy món đang chờ làm");}}
    public void sendKitchen(long orderId)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement ps=c.prepareStatement("UPDATE PhieuGoiMon SET TrangThaiPhieu='DA_GUI_BEP',ThoiGianGuiBep=COALESCE(ThoiGianGuiBep,SYSDATETIME()) WHERE MaPhieu=? AND TrangThaiPhieu IN('MOI','DANG_PHUC_VU')")){ps.setLong(1,orderId);if(ps.executeUpdate()==0)throw new SQLException("Không thể gửi order xuống bếp");}}
    public void readyToPay(long orderId)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement ck=c.prepareStatement("SELECT COUNT(*) FROM ChiTietGoiMon WHERE MaPhieu=? AND TrangThaiCheBien NOT IN('DA_XONG','DA_HUY')")){ck.setLong(1,orderId);try(ResultSet rs=ck.executeQuery()){rs.next();if(rs.getInt(1)>0)throw new SQLException("Vẫn còn món chưa hoàn thành");}try(PreparedStatement ps=c.prepareStatement("UPDATE PhieuGoiMon SET TrangThaiPhieu='CHO_THANH_TOAN' WHERE MaPhieu=?")){ps.setLong(1,orderId);ps.executeUpdate();}try(PreparedStatement ps=c.prepareStatement("UPDATE BanAn SET TrangThai='CHO_THANH_TOAN' WHERE MaBan=(SELECT MaBan FROM PhieuGoiMon WHERE MaPhieu=?)")){ps.setLong(1,orderId);ps.executeUpdate();}}}
    public void cancel(long orderId)throws SQLException{Database.inTransaction(c->{int tableId;try(PreparedStatement ps=c.prepareStatement("SELECT MaBan FROM PhieuGoiMon WITH(UPDLOCK) WHERE MaPhieu=? AND TrangThaiPhieu='MOI'")){ps.setLong(1,orderId);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new SQLException("Chỉ hủy được order chưa gửi bếp");tableId=rs.getInt(1);}}try(PreparedStatement ps=c.prepareStatement("UPDATE PhieuGoiMon SET TrangThaiPhieu='DA_HUY' WHERE MaPhieu=?")){ps.setLong(1,orderId);ps.executeUpdate();}try(PreparedStatement ps=c.prepareStatement("UPDATE BanAn SET TrangThai='TRONG' WHERE MaBan=?")){ps.setInt(1,tableId);ps.executeUpdate();}return null;});}
    private OrderSummary mapSummary(ResultSet rs)throws SQLException{return new OrderSummary(rs.getLong(1),rs.getString(2),rs.getInt(3),rs.getString(4),rs.getString(5),rs.getTimestamp(6).toLocalDateTime(),rs.getString(7),rs.getBigDecimal(8));}
}
